      name: 'Control smart',
      image: 'assets/images/control.png',
    },
    {
      quantity: '1',
      name: 'Cámara interna',
      image: 'assets/images/camaraInterna.png',
    },
  ];

  protected readonly benefits: Benefit[] = [
    {
      icon: 'tool',
      title: 'Instalación profesional',
      description: 'Técnicos especializados.',
    },
    {
      icon: 'gear',
      title: 'Configuración incluida',
      description: 'Dejamos todo listo para usar.',
    },
    {
      icon: 'headset',
      title: 'Soporte personalizado',
      description: 'Te acompañamos siempre.',
    },
    {
      icon: 'shield',
      title: 'Garantía total',
      description: 'Productos y servicio garantizados.',
    },
  ];

  constructor(
    @Inject(DOCUMENT) private readonly document: Document,
    private readonly renderer: Renderer2,
  ) {
    this.updateScrollState();
  }

  @HostListener('window:scroll')
  protected onWindowScroll(): void {
    this.updateScrollState();
  }

  protected toggleMenu(): void {
    this.isMenuOpen.update((isOpen) => {
      const nextState = !isOpen;
      this.syncBodyMenuState(nextState);
      return nextState;
    });
  }

  protected closeMenu(): void {
    if (!this.isMenuOpen()) {
      return;
    }

    this.isMenuOpen.set(false);
    this.syncBodyMenuState(false);
  }

  protected selectedProductIndex(solutionIndex: number): number {
    return this.selectedProducts()[solutionIndex] ?? 0;
  }

  protected selectProduct(solutionIndex: number, productIndex: number): void {
    this.selectedProducts.update(selected => ({ ...selected, [solutionIndex]: productIndex }));
  }

  protected comboWhatsappUrl(solution: SolutionCard): string {
    return this.createWhatsappUrl(
      `Hola ModoConectado, quiero cotizar el combo para ${solution.title}. Me interesa automatizar con Alexa, cámaras y dispositivos inteligentes.`,
    );
  }

  private updateScrollState(): void {
    this.isScrolled.set(this.document.defaultView?.scrollY ? this.document.defaultView.scrollY > 12 : false);
  }

  private createWhatsappUrl(message: string): string {
    return `https://wa.me/${this.whatsappPhone}?text=${encodeURIComponent(message)}`;
  }

  private syncBodyMenuState(isOpen: boolean): void {
    if (isOpen) {
      this.renderer.addClass(this.document.body, 'menu-open');
      return;
    }

    this.renderer.removeClass(this.document.body, 'menu-open');
  }
}
<header class="site-header" [class.site-header--scrolled]="isScrolled()">
  <a class="brand" href="#inicio" aria-label="Ir al inicio" (click)="closeMenu()">
    <span class="brand__mark brand__mark--horizontal" aria-hidden="true">
      <img src="assets/images/logo-horizontal(1).svg" alt="">
    </span>
  </a>

  <nav class="nav" [class.nav--open]="isMenuOpen()" aria-label="Navegación principal">
    <a
      *ngFor="let item of navItems; first as isFirst"
      [class.nav__link--active]="isFirst"
      class="nav__link"
      [href]="'#' + item.target"
      (click)="closeMenu()"
    >
      {{ item.label }}
    </a>
  </nav>

  <a class="quote-link" [href]="whatsappUrl" target="_blank" rel="noreferrer">
    Cotizá ahora
    <span aria-hidden="true">↗</span>
  </a>

  <button
    class="menu-button"
    type="button"
    [attr.aria-expanded]="isMenuOpen()"
    aria-label="Abrir menú"
    (click)="toggleMenu()"
  >
    <span></span>
    <span></span>
  </button>
</header>

